local PlagueDoctorMaskMaker = {}
local PRODUCTS = {
    leather_mask = { name = "Usnjeni mask", leatherCost = 2, herbCost = 1, time = 2, cost = 25, protection = 40, description = "Usnjeni mask za zdravnike kuge." },
    beaked_mask = { name = "Kljunasti mask", leatherCost = 3, herbCost = 2, time = 4, cost = 60, protection = 55, prestige = 2, description = "Kljunasti mask z zelišči v kljunu." },
    silver_beaded_mask = { name = "Srebrno kroglični mask", leatherCost = 3, herbCost = 2, silverCost = 1, time = 6, cost = 140, protection = 70, prestige = 5, happiness = 1, description = "Mask s srebrnimi kroglicami za zdravnike." },
    silver_rim_mask = { name = "Srebrno obrobljeni mask", leatherCost = 3, herbCost = 2, silverCost = 1, goldCost = 1, time = 9, cost = 320, protection = 82, prestige = 10, happiness = 2, description = "Mask s srebrnim robom za plemiške zdravnike." },
    gold_trim_mask = { name = "Zlatorobni mask", leatherCost = 3, herbCost = 2, goldCost = 1, jewelCost = 1, silverCost = 1, time = 12, cost = 700, protection = 92, prestige = 18, happiness = 4, description = "Zlatorobni mask z draguljem za kraljeve zdravnike." },
    royal_grand_mask = { name = "Kraljevski veliki mask", leatherCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, herbCost = 3, time = 17, cost = 1800, protection = 100, prestige = 40, happiness = 8, description = "Veliki kraljevski mask z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Maskarska delavnica", cost = { gold = 280, wood = 120, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    leather_room = { name = "Usnjiška soba", cost = { gold = 900, wood = 250, stone = 400, leather = 10 }, upkeep = 22, qualityBonus = 18 },
    herb_chamber = { name = "Zeliščna komora", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, herb = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_mask_atelier = { name = "Kraljevski atelje mask", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
PlagueDoctorMaskMaker.leatherStock = 18; PlagueDoctorMaskMaker.herbStock = 16; PlagueDoctorMaskMaker.silverStock = 8; PlagueDoctorMaskMaker.goldStock = 6; PlagueDoctorMaskMaker.jewelStock = 6; PlagueDoctorMaskMaker.pearlStock = 4
PlagueDoctorMaskMaker.productStock = {}; PlagueDoctorMaskMaker.buildings = {}; PlagueDoctorMaskMaker.maker = nil; PlagueDoctorMaskMaker.activeMaking = {}; PlagueDoctorMaskMaker.totalProducts = 0; PlagueDoctorMaskMaker.dayTimer = 0
function PlagueDoctorMaskMaker.init() PlagueDoctorMaskMaker.leatherStock=18; PlagueDoctorMaskMaker.herbStock=16; PlagueDoctorMaskMaker.silverStock=8; PlagueDoctorMaskMaker.goldStock=6; PlagueDoctorMaskMaker.jewelStock=6; PlagueDoctorMaskMaker.pearlStock=4; PlagueDoctorMaskMaker.productStock={}; PlagueDoctorMaskMaker.buildings={}; PlagueDoctorMaskMaker.maker=nil; PlagueDoctorMaskMaker.activeMaking={}; PlagueDoctorMaskMaker.totalProducts=0; PlagueDoctorMaskMaker.dayTimer=0; print("[PlagueDoctorMaskMaker] Royal Plague Doctor Mask Maker System initialized (6 products, 4 buildings)") end
function PlagueDoctorMaskMaker.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlagueDoctorMaskMaker.maker={name=n or ("Maskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Maskar najet: %s (spretnost: %d)",PlagueDoctorMaskMaker.maker.name,s),"success") end; return true end
function PlagueDoctorMaskMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlagueDoctorMaskMaker.build(id) local ok,e=PlagueDoctorMaskMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlagueDoctorMaskMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlagueDoctorMaskMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlagueDoctorMaskMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlagueDoctorMaskMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.leatherCost and PlagueDoctorMaskMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.herbCost and PlagueDoctorMaskMaker.herbStock<(d.herbCost or 0) then return false,"Premalo zelišč" end; if d.silverCost and PlagueDoctorMaskMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlagueDoctorMaskMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlagueDoctorMaskMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlagueDoctorMaskMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlagueDoctorMaskMaker.buildings==0 then return false,"Potrebna delavnica" end; if not PlagueDoctorMaskMaker.maker then return false,"Potreben maskar" end; return true end
function PlagueDoctorMaskMaker.make(pt,qty) qty=qty or 1; local ok,e=PlagueDoctorMaskMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.leatherCost then PlagueDoctorMaskMaker.leatherStock=PlagueDoctorMaskMaker.leatherStock-d.leatherCost*qty end; if d.herbCost then PlagueDoctorMaskMaker.herbStock=PlagueDoctorMaskMaker.herbStock-d.herbCost*qty end; if d.silverCost then PlagueDoctorMaskMaker.silverStock=PlagueDoctorMaskMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlagueDoctorMaskMaker.goldStock=PlagueDoctorMaskMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlagueDoctorMaskMaker.jewelStock=PlagueDoctorMaskMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlagueDoctorMaskMaker.pearlStock=PlagueDoctorMaskMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlagueDoctorMaskMaker.maker then t=math.max(1,t-math.floor(PlagueDoctorMaskMaker.maker.skill/12)) end; table.insert(PlagueDoctorMaskMaker.activeMaking,{id="plaguemask_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,protection=d.protection or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlagueDoctorMaskMaker.completeMaking(m) local q=1.0+(PlagueDoctorMaskMaker.getQualityBonus()/100); if PlagueDoctorMaskMaker.maker then q=q+(PlagueDoctorMaskMaker.maker.skill/180) end; q=math.min(2.0,q); PlagueDoctorMaskMaker.productStock[m.productType]=(PlagueDoctorMaskMaker.productStock[m.productType] or 0)+m.quantity; PlagueDoctorMaskMaker.totalProducts=PlagueDoctorMaskMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlagueDoctorMaskMaker.maker then PlagueDoctorMaskMaker.maker.itemsMade=PlagueDoctorMaskMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then PlagueDoctorMaskMaker.maker.skill=math.min(100,PlagueDoctorMaskMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mask izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plaguemask.completed",{productName=m.productName,protection=m.protection,prestige=m.prestige,happiness=m.happiness}) end end
function PlagueDoctorMaskMaker.update(dt) if not _G.state then return end; PlagueDoctorMaskMaker.dayTimer=PlagueDoctorMaskMaker.dayTimer+dt; if PlagueDoctorMaskMaker.dayTimer>=30 then PlagueDoctorMaskMaker.dayTimer=0; for i=#PlagueDoctorMaskMaker.activeMaking,1,-1 do local m=PlagueDoctorMaskMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlagueDoctorMaskMaker.completeMaking(m); table.remove(PlagueDoctorMaskMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlagueDoctorMaskMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlagueDoctorMaskMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlagueDoctorMaskMaker.getStats() return {leatherStock=PlagueDoctorMaskMaker.leatherStock,herbStock=PlagueDoctorMaskMaker.herbStock,silverStock=PlagueDoctorMaskMaker.silverStock,goldStock=PlagueDoctorMaskMaker.goldStock,jewelStock=PlagueDoctorMaskMaker.jewelStock,pearlStock=PlagueDoctorMaskMaker.pearlStock,productStock=PlagueDoctorMaskMaker.productStock,numBuildings=#PlagueDoctorMaskMaker.buildings,hasMaker=PlagueDoctorMaskMaker.maker~=nil,makerName=PlagueDoctorMaskMaker.maker and PlagueDoctorMaskMaker.maker.name or "—",makerSkill=PlagueDoctorMaskMaker.maker and PlagueDoctorMaskMaker.maker.skill or 0,activeMaking=#PlagueDoctorMaskMaker.activeMaking,totalProducts=PlagueDoctorMaskMaker.totalProducts} end
return PlagueDoctorMaskMaker
